import {examSection,mountExam,openExamHash} from './exam.js';
import {playNative,stopNative,updateNativeRate,spellWord,nativeKey,letters,letterIPA} from './pronunciation.js';
import {neuralSpeak,stopVoice,choose,selection,updateAudioRate} from './voice.js';
import {lessons,sounds} from './course.js';
history.scrollRestoration='manual';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let progress=read('wortreise-progress',[]),saved=read('wortreise-saved',[]),rate=read('wortreise-rate',1),voiceName=read('wortreise-voice',''),currentLesson=null,quizIndex=0,passed=new Set(),lastSpoken='Hallo',recorder=null,recordURL=null,recordTimer,sceneToken=0,worker=null,mediaURL=null,cues=[],captionBusy=false;
const words=lessons.flatMap(l=>l.words.map(w=>({de:w[0],en:w[1],lesson:l.id,category:l.title})));
function persist(key,val){try{localStorage.setItem(key,JSON.stringify(val))}catch{toast('Your browser could not save progress. You can still keep learning.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
async function speak(text,lang='de-DE'){lastSpoken=text;stopNative();try{if(lang.startsWith('de')&&nativeKey(text)){stopVoice();$$('[data-voice-status]').forEach(el=>el.textContent='Human-recorded German audio · '+text);await playNative(text,rate)}else await neuralSpeak(text,rate,lang)}catch(e){toast(e.message)}}
function soundButton(text){return `<button class="sound" data-speak="${esc(text)}" aria-label="Listen to ${esc(text)}">▷</button>`}
function intro(k,title,description){return `<div class="page-intro"><div class="eyebrow">${k}</div><h1>${title}</h1><p>${description}</p></div>`}
function controls(){return `<div class="controls"><label>Playback speed <input class="speed-slider" aria-label="Playback speed" type="range" min="0.5" max="1.25" step="0.05" value="${rate}"><output class="speed-output">${rate.toFixed(2)}×</output></label><button class="pill" data-action="stop">Stop audio ◼</button><span class="micro">Pitch-preserving slow playback</span></div>`}
function fillVoices(){}
const art=`<div class="sun"></div><div class="postcard"><svg viewBox="0 0 260 170" aria-hidden="true"><path d="M0 135Q65 109 130 138T260 130V170H0" fill="#a9c39d"/><g stroke="#476b55" stroke-width="2"><path d="M20 132V63l22-20 22 20v69" fill="#f1ce99"/><path d="M24 64h36M28 76h9v15h-9zm18 0h9v15h-9zm-18 27h9v15h-9zm18 0h9v15h-9z" fill="#f9f2d8"/><path d="M76 132V77l24-23 24 23v55" fill="#c5d2ae"/><path d="M74 77h52M86 89h10v14H86zm18 0h10v14h-10z" fill="#f9f2d8"/><path d="M143 132V52h19v80M148 52V35h9v17M152 35V8" fill="#e9dfb9"/><ellipse cx="152" cy="54" rx="13" ry="7" fill="#749375"/><path d="M175 132V69l24-23 24 23v63" fill="#d69473"/><path d="M181 70h36M184 82h10v14h-10zm19 0h10v14h-10zm-19 24h10v14h-10zm19 0h10v14h-10z" fill="#f8ebce"/><path d="M229 133V95h22v38" fill="#e8cc98"/></g><path d="M0 146h260M0 151h260" stroke="#73916b" stroke-width="2"/></svg><p>Grüße aus Deutschland</p></div><div class="bubble">Hallo! <span aria-hidden="true">✧</span></div><div class="mini-bubble">/haˈloː/ &nbsp; Hello, you.</div><span class="spark" aria-hidden="true">✳</span>`;
function home(){let next=lessons.find(l=>!progress.includes(l.id))||lessons[0];return `<section class="hero"><div><div class="hero-label">✦ &nbsp; GERMAN, REIMAGINED.</div><h1>New language.<br><em>New frequency.</em></h1><p>Tune into German with neural voices, immersive lessons, and endless practice. Your next world starts with a sound.</p><div class="row"><button class="btn" data-lesson="${next.id}">${progress.length?'Continue your journey':'Let’s start with Hallo'} <span>↗</span></button><a class="text-link" href="#sounds">Explore the sounds &nbsp;▷</a></div></div><div class="hero-art chrome-art"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="chrome-sphere"><span>ü</span></div><div class="orbit-tag tag-de">DE / NATIVE FREQUENCY</div><div class="orbit-tag tag-voice">◉ MALE + FEMALE</div><span class="orbit-star">✦</span></div></section><div class="stats"><div class="stat"><span class="stat-icon">▤</span><div><strong>${progress.length}<span class="micro"> / 12</span></strong><small>Lessons completed</small></div></div><div class="stat"><span class="stat-icon">♡</span><div><strong data-saved-count>${saved.length}</strong><small>Words to revisit</small></div></div><div class="stat"><span class="stat-icon">◷</span><div><strong>5–10 <span class="micro">min</span></strong><small>A little time for you</small></div></div></div><div class="section-top"><div><h2>Your next little step</h2><p>Start where you are. We’ll take it from here.</p></div><a href="#learn" class="text-link">View learning path ↗</a></div><div class="dashboard-grid"><div class="card lesson-preview"><div class="illustration">${next.icon}</div><div style="flex:1"><div class="tag">${esc(next.category.toUpperCase())} · ${String(lessons.indexOf(next)+1).padStart(2,'0')}</div><h3>${esc(next.title)}</h3><p>${esc(next.subtitle)}</p><div class="progress"><span style="width:${progress.length/12*100}%"></span></div><div class="row" style="justify-content:space-between"><span class="micro">${next.minutes} minutes · Listen, learn & try</span><button class="btn small-btn" data-lesson="${next.id}">Start lesson →</button></div></div></div><div class="card word-day"><div class="eyebrow">A WORD TO TAKE WITH YOU</div><h3 lang="de">die Vorfreude</h3>${soundButton('die Vorfreude')}<p>The joy of looking forward to something.</p><p style="font-style:italic">Like your next little adventure.</p><button class="save" data-custom-save="die Vorfreude" aria-pressed="${saved.includes('die Vorfreude')}">♡ Save this word</button></div></div><div class="section-top"><div><h2>Make German your own</h2><p>A few good tools for the way you learn.</p></div></div><div class="tool-grid"><a class="tool-card" href="#sounds"><span class="tool-symbol">◉</span><h3>Hear it. Say it. Feel it.</h3><p>Slow things down. Discover German sounds and find your voice.</p><span class="text-link">Enter the sound studio <span>↗</span></span></a><a class="tool-card" href="#translate"><span class="tool-symbol">⇄</span><h3>A bridge between words</h3><p>Translate a thought, hear it in German, and take it into your day.</p><span class="text-link">Try the translator <span>↗</span></span></a><a class="tool-card" href="#captions"><span class="tool-symbol">▣</span><h3>Every word. Every feeling.</h3><p>Follow conversations with speaker, tone and sound captions.</p><span class="text-link">Explore accessible captions <span>↗</span></span></a></div><div class="banner"><span style="font-size:21px">✧</span><p><strong>You don’t need to know a single word to begin.</strong><br>Just bring your curiosity. The first “Hallo” is already a conversation. <a class="text-link" href="#infinite">Try infinite practice ∞</a> · <a class="text-link" href="#exam">Semester exam revision ↗</a></p></div>`}
function learn(){return intro('YOUR LEARNING PATH','A little further, every day.','Twelve gentle lessons, from your first hello to telling a story. Every lesson includes English explanations, audio, a conversation, and a short check. Explore in order or revisit any lesson.')+`<div class="progress"><span style="width:${progress.length/12*100}%"></span></div><p class="micro">${progress.length} of 12 lessons completed · Progress stays on this device</p><div class="grid">${lessons.map((l,i)=>`<article class="card lesson-card"><div class="row" style="justify-content:space-between"><span class="lesson-icon">${l.icon}</span><span class="micro">${progress.includes(l.id)?'✓ Completed':String(i+1).padStart(2,'0')}</span></div><div class="tag">${esc(l.category.toUpperCase())}</div><h3>${esc(l.title)}</h3><p>${esc(l.subtitle)}</p><span class="micro">${l.minutes} min · ${l.words.length} useful words & phrases</span><button class="btn ${progress.includes(l.id)?'secondary':''}" data-lesson="${l.id}">${progress.includes(l.id)?'Revisit lesson':'Start lesson'} →</button></article>`).join('')}</div>`}
function soundStudio(){return intro('SOUND STUDIO','Find your German voice.','Listen closely, slow it down, and give it a go. Start with the alphabet, then explore the sounds that make German distinctive.')+controls()+`<div class="two-col"><section class="card"><h2>Meet the alphabet</h2><p class="muted">Tap a letter to hear a human-recorded German letter name. These are letter names, not the sounds they make inside every word. Spelling uses these recordings rather than synthesized letter names.</p><div class="letter-grid">${letters.map((c,i)=>`<button class="letter" data-letter="${c}" data-speak="${c}" aria-label="Hear the German name of ${c}">${c}<small>/${letterIPA[i]}/</small></button>`).join('')}</div><h3 style="margin-top:25px">A few special sounds</h3><div class="row">${sounds.map((s,i)=>`<button class="pill" data-sound="${i}">${s[0]}</button>`).join('')}</div><div id="sound-detail" class="sound-detail"><h3>Ü · Round lips, forward tongue</h3><p>${sounds[2][2]}</p><div class="row">${soundButton('grün')}<strong lang="de">grün</strong><span class="muted">green</span></div></div></section><section class="card"><div class="eyebrow">LISTEN → REPEAT → LISTEN AGAIN</div><h2 style="margin-top:12px">Your own little practice room</h2><label class="field">Your practice word or sentence<input id="speak-text" value="Straße" maxlength="250" lang="de"></label><div class="special-keys">${['ä','ö','ü','ß','Ä','Ö','Ü'].map(c=>`<button data-insert="${c}" data-target="speak-text">${c}</button>`).join('')}</div><div class="row"><button class="btn" data-action="listen-practice">▷ Hear the word or sentence</button><button class="pill" data-action="spell-practice">Spell letter by letter</button><button class="pill" data-action="repeat-practice">Repeat 3 times</button><button class="btn secondary" id="record-btn" data-action="record">● Record yourself</button></div><div class="spelling-panel"><div class="eyebrow">HUMAN-RECORDED SPELLING</div><div id="spelling-track" class="spelling-track" aria-hidden="true"></div><p id="spelling-status" role="status">Each letter is played separately, with clear pauses. Try Straße, grün or Äpfel. Ä, Ö, Ü and ß each have their own recording. Spelling supports letters and spaces; punctuation is skipped.</p><button class="pill" data-action="stop">Stop spelling ◼</button><a class="audio-credit" href="audio/credits.html" target="_blank" rel="noopener">Recording sources & credits ↗</a></div><p class="micro">Record, then compare your voice with the model. Your recording stays in this tab and is discarded when you leave or reload.</p><audio id="recording" controls hidden aria-label="Your pronunciation recording"></audio><button class="pill" id="recognize-btn" data-action="recognize">🎙 Check what the browser hears</button><p class="micro">Optional speech recognition may send audio to your browser’s speech service. A word match is practice feedback, not a pronunciation grade.</p><div id="speech-feedback" class="feedback" aria-live="polite"></div><div class="notice">Make it a habit: listen once, repeat three times, then use the word in your own sentence. The alphabet and selected sound examples use credited human recordings. Other words and sentences use your selected neural voice. Spelling names each letter; normal word pronunciation joins sounds together.</div></section></div>`}
function practice(){return intro('WORDS & PRACTICE','Make those words stick.','Listen, spell, and revisit your favourites. Learn nouns together with their article; it makes future sentences much easier.')+controls()+`<div class="two-col"><div class="card"><h2>Listen & spell</h2><p class="muted">Listen without reading, then type the German phrase. Accents and umlauts matter.</p><button class="btn" data-action="dictate">▷ Play a practice phrase</button><label class="field">What did you hear?<input id="dictation" autocomplete="off" spellcheck="false" lang="de"></label><div class="special-keys">${['ä','ö','ü','ß'].map(c=>`<button data-insert="${c}" data-target="dictation">${c}</button>`).join('')}</div><div class="row"><button class="btn secondary" data-action="check-dictation">Check spelling</button><button class="pill" data-action="reveal-dictation">Show the phrase</button></div><div id="dictation-feedback" class="feedback" aria-live="polite"></div></div><div class="card"><h2>Your word collection</h2><p class="muted">Save a word when you want to meet it again. Your collection is stored on this device.</p><label class="field">Find a word<input class="search" id="word-search" placeholder="Search German or English…"></label><label class="field">Show<select id="word-filter"><option value="all">All words & phrases</option><option value="saved">My saved words</option>${lessons.map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join('')}</select></label><span class="micro" id="word-count"></span></div></div><div id="words" class="word-list"></div>`}
let dictationWord=null;
function renderWords(){let q=$('#word-search').value.toLocaleLowerCase(),filter=$('#word-filter').value;let list=[...words,{de:'die Vorfreude',en:'the joy of anticipation',lesson:'extra',category:'A word to take with you'}].filter(w=>(w.de+' '+w.en).toLowerCase().includes(q)&&(filter==='all'||(filter==='saved'?saved.includes(w.de):w.lesson===filter)));$('#word-count').textContent=`${list.length} words & phrases`;$('#words').innerHTML=list.map(w=>`<article class="word-card"><strong lang="de">${esc(w.de)}</strong>${soundButton(w.de)}<p>${esc(w.en)}</p><span class="micro">${esc(w.category)}</span><br><button class="save" data-custom-save="${esc(w.de)}" aria-pressed="${saved.includes(w.de)}">${saved.includes(w.de)?'♥ Saved':'♡ Save word'}</button></article>`).join('')||'<p class="muted">No words here yet. Try another search or save a word you like.</p>'}
function translator(){return intro('TRANSLATOR','A thought, in another language.','Translate between English and German, listen at your own pace, then practise saying it aloud.')+controls()+`<div class="two-col"><section class="card"><div class="row"><label class="field">From<select id="source-lang"><option value="en">English</option><option value="de">German</option></select></label><button class="pill" data-action="swap">⇄ Swap languages</button><strong id="target-label">German</strong></div><label class="field">Your words<textarea id="translate-input" maxlength="450" placeholder="What would you like to say?">Hello! How are you?</textarea></label><div class="row"><button id="translate-btn" class="btn" data-action="translate">Translate →</button><span class="micro">Up to 450 UTF-8 bytes per request</span></div><p class="micro">Translation sends this text to MyMemory. Don’t enter private information. Free service limits may apply. Check machine translations before relying on them.</p><div id="translate-status" class="feedback" aria-live="polite"></div></section><section class="card"><div class="eyebrow">YOUR TRANSLATION</div><div id="translation" class="result" style="margin-top:16px">Your translated words will appear here.</div><div class="row" style="margin-top:17px"><button class="btn secondary" data-action="hear-translation">▷ Listen</button><button class="pill" data-action="copy-translation">Copy text</button><button class="pill" data-action="practice-translation">Practise aloud ↗</button></div><div class="notice" style="margin-top:20px">Want to preserve the speaker and feeling? Send your translation to the Caption studio and add an editable tone or sound cue.</div><button class="pill" style="margin-top:15px" data-action="caption-translation">Make a caption →</button></section></div>`}
let translationText='',translationLang='de';
async function translateText(text,from='en',to='de'){if(!text.trim())throw Error('Enter some words first.');if(new TextEncoder().encode(text).length>450)throw Error('Please shorten this text to 450 UTF-8 bytes (special characters can use more than one byte).');let res=await fetch('https://api.mymemory.translated.net/get?'+new URLSearchParams({q:text,langpair:`${from}|${to}`}),{signal:AbortSignal.timeout(20000)});if(!res.ok)throw Error('The translation service is unavailable. Please try again later.');let d=await res.json();if(Number(d.responseStatus)!==200||!d.responseData?.translatedText)throw Error(d.responseDetails||'Translation limit reached. Please try again later.');const doc=new DOMParser().parseFromString(d.responseData.translatedText,'text/html');return doc.body.textContent}
const sampleCues=()=>[{start:0,end:3,speaker:'Anna',tone:'cheerful',sound:'',text:'Hallo! Schön, dich zu sehen.',translation:'Hello! Lovely to see you.'},{start:3,end:6,speaker:'Ben',tone:'pleased',sound:'',text:'Hallo, Anna! Wie geht es dir?',translation:'Hello, Anna! How are you?'},{start:6,end:9,speaker:'Anna',tone:'happy',sound:'laughter',text:'Mir geht es gut, danke!',translation:'I am well, thank you!'}];
function captions(){return intro('ACCESSIBLE CAPTION STUDIO','Every word. Every feeling.','Read along with speaker labels, tone, and meaningful sounds. Explore a sample conversation or create captions for your own short audio or video.')+`<div class="two-col"><section class="card"><div class="eyebrow">A CONVERSATION, WITH CONTEXT</div><div class="caption-screen" style="margin-top:16px"><div><small id="caption-time">EDITABLE SDH CAPTIONS</small><p id="live-caption" lang="de">Anna [cheerful]: Hallo! Schön, dich zu sehen.</p><small id="live-translation">Hello! Lovely to see you.</small></div></div><div class="row" style="margin-top:15px"><button class="btn" data-action="play-captions">▷ Play conversation</button><button class="pill" data-action="stop">Stop</button><button class="pill" data-action="sample-captions">Load sample</button></div>${controls()}<div id="media-container"></div><div class="notice">SDH includes dialogue, speakers, tone, and important sounds. Automatic transcription drafts the spoken words. Review timestamps and add speaker, emotion, and sound cues yourself; they are not automatically detected.</div></section><section class="card"><h2>Bring your own conversation</h2><p class="muted">Choose a short clip. Speech-to-text runs on your device after a one-time model download. First use can take several minutes; desktop devices are usually faster.</p><label class="field">Audio or video · up to 30 MB, 3 minutes<input id="media-file" type="file" accept="audio/*,video/*"></label><label class="field">Spoken language<select id="media-lang"><option value="german">German</option><option value="english">English</option></select></label><div class="row"><button class="btn" id="transcribe-btn" data-action="transcribe">Generate transcript</button><button class="pill" data-action="cancel-transcription" id="cancel-transcription" hidden>Cancel</button></div><p class="micro">The model downloads from Hugging Face. Media stays in this browser. Supported formats depend on your browser; MP3 and WAV are the most reliable. Video needs a browser-decodable audio track.</p><div id="caption-status" role="status" class="feedback"></div><label class="field">Or import an existing SRT / VTT file<input id="caption-import" type="file" accept=".srt,.vtt"></label><div class="row"><button class="pill" data-action="add-cue">+ Add caption</button><button class="pill" id="translate-captions" data-action="translate-captions">Translate dialogue</button></div><p class="micro">Translation sends caption dialogue to MyMemory. Source German is translated to English; source English to German. Service limits apply.</p></section></div><div class="section-top"><div><h2>Review & make it accessible</h2><p>Edit every line. Add only cues that you hear or intend.</p></div><div class="row"><button class="pill" data-action="export-srt">↓ SRT</button><button class="btn small-btn" data-action="export-vtt">↓ WebVTT</button></div></div><label class="field" style="max-width:260px">Export language<select id="export-lang"><option value="original">Original dialogue</option><option value="translation">Translated dialogue</option></select></label><div id="cues" class="cue-list"></div>`}
function renderCues(){if(!$('#cues'))return;$('#cues').innerHTML=cues.map((c,i)=>`<div class="cue" data-cue="${i}"><div class="row"><strong class="micro">${String(i+1).padStart(2,'0')}</strong><label class="micro">From (s) <input data-cue-field="start" type="number" min="0" step="0.1" value="${c.start}" aria-label="Caption ${i+1} start seconds"></label><label class="micro">To (s) <input data-cue-field="end" type="number" min="0" step="0.1" value="${c.end}" aria-label="Caption ${i+1} end seconds"></label><input data-cue-field="speaker" value="${esc(c.speaker)}" placeholder="Speaker" aria-label="Caption ${i+1} speaker"><input data-cue-field="tone" value="${esc(c.tone)}" placeholder="Tone: excited" aria-label="Caption ${i+1} emotion or tone"><input data-cue-field="sound" value="${esc(c.sound)}" placeholder="Sound: laughter" aria-label="Caption ${i+1} sound cue"><button class="pill" data-delete-cue="${i}">Remove</button></div><label class="sr-only" for="cue-text-${i}">Caption ${i+1} dialogue</label><textarea id="cue-text-${i}" data-cue-field="text">${esc(c.text)}</textarea><label class="field">Translation<input data-cue-field="translation" value="${esc(c.translation)}" placeholder="Translated dialogue"></label></div>`).join('')||'<p class="muted">Add a caption, load the sample, import a file, or generate a transcript to begin.</p>'}
function captionLine(c,translated=false){return `${c.sound?'['+c.sound+'] ':''}${c.speaker?c.speaker+' ':''}${c.tone?'['+c.tone+']':''}${c.speaker||c.tone?': ':''}${translated?c.translation:c.text}`.trim()}
function showCue(c){if(!c)return;$('#live-caption').textContent=captionLine(c);$('#live-translation').textContent=c.translation||'';$('#caption-time').textContent=`${c.start.toFixed(1)}s – ${c.end.toFixed(1)}s`}
function download(name,text,type='text/plain'){let url=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function stamp(s,sep='.'){let n=Math.round(s*1000);return [Math.floor(n/3600000),Math.floor(n/60000)%60,Math.floor(n/1000)%60].map(x=>String(x).padStart(2,'0')).join(':')+sep+String(n%1000).padStart(3,'0')}
function exportCaptions(vtt){if(!cues.length)return toast('Add a caption first.');let trans=$('#export-lang').value==='translation';for(let c of cues){if(!Number.isFinite(c.start)||!Number.isFinite(c.end)||c.start<0||c.end<=c.start)return toast('Each caption needs a valid start time and a later end time.');if(trans&&!c.translation.trim())return toast('Add a translation for every caption before exporting translated dialogue.')}let ordered=[...cues].sort((a,b)=>a.start-b.start);download('wortreise-captions.'+(vtt?'vtt':'srt'),(vtt?'WEBVTT\n\n':'')+ordered.map((c,i)=>`${i+1}\n${stamp(c.start,vtt?'.':',')} --> ${stamp(c.end,vtt?'.':',')}\n${captionLine(c,trans).replace(/-->/g,'→')}\n`).join('\n'),vtt?'text/vtt':'text/plain')}
function importCaptions(text){let parts=text.replace(/\r/g,'').split(/\n\s*\n/),out=[];for(let block of parts){let lines=block.split('\n'),idx=lines.findIndex(l=>l.includes('-->'));if(idx<0)continue;let times=lines[idx].match(/(?:(\d+):)?(\d{2}):(\d{2})[.,](\d{3})\s*-->\s*(?:(\d+):)?(\d{2}):(\d{2})[.,](\d{3})/);if(!times)continue;let start=Number(times[1]||0)*3600+Number(times[2])*60+Number(times[3])+Number(times[4])/1000,end=Number(times[5]||0)*3600+Number(times[6])*60+Number(times[7])+Number(times[8])/1000;out.push({start,end,text:lines.slice(idx+1).join('\n').replace(/<[^>]*>/g,''),speaker:'',tone:'',sound:'',translation:''})}if(!out.length)throw Error('No valid timed captions found. Choose an SRT or WebVTT file.');return out}
function attachMedia(){if(!mediaURL||!$('#media-container'))return;let file=$('#media-file')?.files[0];let el=document.createElement(file?.type.startsWith('video')?'video':'audio');el.controls=true;el.className='media-preview';el.src=mediaURL;el.playbackRate=rate;el.ontimeupdate=()=>{let c=cues.find(c=>el.currentTime>=c.start&&el.currentTime<c.end);if(c)showCue(c);else{$('#live-caption').textContent='';$('#live-translation').textContent=''}};$('#media-container').replaceChildren(el)}
function cancelTranscription(){worker?.terminate();worker=null;captionBusy=false;$('#transcribe-btn')?.removeAttribute('disabled');if($('#cancel-transcription'))$('#cancel-transcription').hidden=true}
async function transcribe(){let file=$('#media-file').files[0];if(!file)return toast('Choose an audio or video clip first.');if(file.size>30*1024*1024)return toast('Choose a clip smaller than 30 MB.');if(captionBusy)return;captionBusy=true;$('#transcribe-btn').disabled=true;$('#cancel-transcription').hidden=false;const status=t=>{if($('#caption-status'))$('#caption-status').textContent=t};try{status('Decoding your clip…');const context=new AudioContext();let decoded;try{decoded=await context.decodeAudioData(await file.arrayBuffer())}finally{await context.close()}if(decoded.duration>180)throw Error('Choose a clip under three minutes.');const offline=new OfflineAudioContext(1,Math.ceil(decoded.duration*16000),16000);let src=offline.createBufferSource();src.buffer=decoded;src.connect(offline.destination);src.start();const buffer=await offline.startRendering();if(!captionBusy)return;const audio=buffer.getChannelData(0);status('Preparing the speech model. First use downloads the model and may take several minutes…');worker=new Worker('transcribe-worker.js',{type:'module'});worker.onmessage=({data})=>{if(data.type==='progress')status(data.message);if(data.type==='error'){status('Could not transcribe: '+data.message);cancelTranscription()}if(data.type==='done'){cues=(data.result.chunks||[]).filter(c=>c.text.trim()).map(c=>({start:Math.max(0,c.timestamp[0]??0),end:Math.min(decoded.duration,c.timestamp[1]??decoded.duration),text:c.text.trim(),speaker:'',tone:'',sound:'',translation:''}));if(!cues.length&&data.result.text?.trim())cues=[{start:0,end:decoded.duration,text:data.result.text.trim(),speaker:'',tone:'',sound:'',translation:''}];renderCues();status(cues.length?'Transcript ready. Review the words and timing, then add speaker, tone and sound cues.':'No speech found. Try a clearer clip.');cancelTranscription()}};worker.onerror=()=>{status('The model could not start on this browser. Try desktop Chrome/Edge, or import an SRT/VTT file.');cancelTranscription()};worker.postMessage({audio,language:$('#media-lang').value},[audio.buffer])}catch(e){status(e.message||'Your browser could not decode this clip. Try an MP3 or WAV file.');cancelTranscription()}}
function openLesson(id){currentLesson=lessons.find(l=>l.id===id);if(!currentLesson)return;quizIndex=0;passed=new Set();let l=currentLesson;$('#lesson-body').innerHTML=`<div class="eyebrow">LESSON ${lessons.indexOf(l)+1} · ${l.minutes} MINUTES</div><h2 id="lesson-title">${l.icon} ${esc(l.title)}</h2><p class="muted">${esc(l.subtitle)}</p><p>Listen to each phrase. Repeat it slowly, then say it once without reading.</p><div class="controls"><label for="lesson-rate">Playback speed <input id="lesson-rate" type="range" min="0.5" max="1.25" step="0.05" value="${rate}"><output id="lesson-rate-out">${rate.toFixed(2)}×</output></label><button class="pill" data-action="stop">Stop audio ◼</button><label>German voice <select data-neural-voice aria-label="Lesson German voice"><option value="de_DE-thorsten-medium">Thorsten · Male · Fast neural</option><option value="de_DE-thorsten-high">Thorsten · Male · Studio</option><option value="de_DE-kerstin-low">Kerstin · Female · Neural</option><option value="device">Device voice</option></select></label></div><div class="lesson-words">${l.words.map(w=>`<div class="lesson-word">${soundButton(w[0])}<span lang="de"><strong>${esc(w[0])}</strong><small lang="en">${esc(w[1])}</small></span><button class="save" data-custom-save="${esc(w[0])}" aria-pressed="${saved.includes(w[0])}">${saved.includes(w[0])?'♥':'♡'} Save</button></div>`).join('')}</div><div class="grammar"><h3>A little understanding</h3><p>${esc(l.rule)}</p><div class="lesson-word">${soundButton(l.example[0])}<span lang="de"><strong>${esc(l.example[0])}</strong><small lang="en">${esc(l.example[1])}</small></span></div></div><h3>A real little conversation</h3>${l.scene.map(s=>`<p><strong>${s[0]} [${s[1]}]:</strong> <span lang="de">${esc(s[2])}</span><br><small class="muted">${esc(s[3])}</small></p>`).join('')}<button class="pill" data-action="play-lesson">▷ Listen to the conversation</button><p class="micro">Caption tone labels describe this authored scene. Device voices may not express every emotion.</p><div class="quiz"><div id="quiz-body"></div></div><div class="row" style="margin-top:20px"><button class="btn" id="complete-lesson" data-action="complete-lesson" disabled>Complete all 3 checks to finish</button><span class="micro">Your progress is saved on this device.</span></div>`;renderQuiz();$$('[data-neural-voice]').forEach(el=>el.value=selection());syncSaved();$('#lesson-dialog').showModal()}
function normalize(t){return t.toLocaleLowerCase('de').normalize('NFC').trim().replace(/[.!?,;:]/g,'').replace(/\s+/g,' ')}
function renderQuiz(){let q=currentLesson.quiz[quizIndex];$('#quiz-body').innerHTML=`<div class="eyebrow">YOUR TURN · ${quizIndex+1} / ${currentLesson.quiz.length}</div><p>${esc(q[0])}</p><label class="sr-only" for="quiz-answer">Your answer</label><input id="quiz-answer" lang="de" autocomplete="off" spellcheck="false"><div class="special-keys">${['ä','ö','ü','ß'].map(c=>`<button data-insert="${c}" data-target="quiz-answer">${c}</button>`).join('')}</div><div class="row"><button class="btn small-btn" data-action="check-quiz">Check answer</button><button class="pill" data-action="show-quiz">Show answer</button><button class="pill" data-action="next-quiz">Next →</button></div><div class="feedback" id="quiz-feedback" aria-live="polite"></div>`}
function route(){
 const main=$('#content');
 if(!main.dataset.ready){
  const parts=[['home',home],['learn',learn],['exam',()=>examSection(rate)],['sounds',soundStudio],['practice',practice],['translate',translator],['captions',captions]];
  main.innerHTML=parts.map(([id,fn],i)=>`<section class="scroll-section" id="${id}" aria-label="${id}"><div class="section-index"><span>0${i+1} / ${id.toUpperCase()}</span><span>WORTREISE STUDIO ↗</span></div>${fn()}</section>`).join('')+`<section id="infinite" class="scroll-section"><div class="section-index"><span>08 / INFINITE PRACTICE</span><span>STAY IN THE FLOW ∞</span></div>${intro('NO FINISH LINE','Stay on the frequency.','Keep scrolling for another word, another listen, another chance to make it yours. These review cards revisit your lesson vocabulary.')}<div id="endless-cards" class="word-list"></div><div id="more-practice" class="load-marker">∞ &nbsp; More practice as you scroll</div></section>`;
  main.dataset.ready='true';mountExam();renderWords();$('#word-search').oninput=renderWords;$('#word-filter').onchange=renderWords;
  if(!cues.length)cues=sampleCues();renderCues();showCue(cues[0]);
  $('#media-file').onchange=()=>{if(mediaURL)URL.revokeObjectURL(mediaURL);mediaURL=$('#media-file').files[0]?URL.createObjectURL($('#media-file').files[0]):null;attachMedia()};
  $('#caption-import').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('Choose a caption file under 1 MB.');cues=importCaptions(await file.text());renderCues();toast('Captions imported. Review timing and labels.')}catch(err){toast(err.message)}};
  appendPractice();new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))appendPractice()},{rootMargin:'400px'}).observe($('#more-practice'));
  const spy=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting)$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===entry.target.id))},{rootMargin:'-15% 0px -65% 0px'});$$('.scroll-section').forEach(el=>spy.observe(el));
 }
 const name=location.hash.slice(1)||'home';openExamHash(name);if(name!=='content')document.getElementById(name)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
}
let practiceCount=0,practiceDeck=[];
function nextReview(){if(!practiceDeck.length){practiceDeck=[...words];for(let i=practiceDeck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[practiceDeck[i],practiceDeck[j]]=[practiceDeck[j],practiceDeck[i]]}}return practiceDeck.pop()}
function syncSaved(){
 $$('[data-custom-save]').forEach(button=>{const active=saved.includes(button.dataset.customSave);button.textContent=active?'♥ Saved':'♡ Save word';button.setAttribute('aria-pressed',String(active))});
 $$('[data-saved-count]').forEach(el=>el.textContent=saved.length);
 if($('#word-filter')?.value==='saved')renderWords();
}
function appendPractice(){let list=$('#endless-cards');if(!list)return;let batch=Array.from({length:9},()=>nextReview());list.insertAdjacentHTML('beforeend',batch.map(w=>`<article class="word-card endless-card"><span class="eyebrow">SIGNAL ${String(++practiceCount).padStart(3,'0')}</span><h3>${esc(w.en)}</h3><p>How would you say this in German?</p><details><summary>Reveal the phrase</summary><p lang="de" class="reveal-word">${esc(w.de)}</p></details><div class="row">${soundButton(w.de)}<button class="save" data-custom-save="${esc(w.de)}" aria-pressed="${saved.includes(w.de)}">${saved.includes(w.de)?'♥ Saved':'♡ Save word'}</button></div></article>`).join(''));syncSaved()}
window.addEventListener('hashchange',route);window.speechSynthesis?.addEventListener('voiceschanged',fillVoices);
document.addEventListener('input',e=>{if(e.target.matches('.speed-slider,#lesson-rate')){rate=Number(e.target.value);persist('wortreise-rate',rate);$$('.speed-slider,#lesson-rate').forEach(el=>el.value=rate);$$('.speed-output,#lesson-rate-out').forEach(el=>el.textContent=rate.toFixed(2)+'×');updateAudioRate(rate);updateNativeRate(rate);$$('audio,video').forEach(el=>el.playbackRate=rate)}if(e.target.dataset.cueField){let i=Number(e.target.closest('[data-cue]').dataset.cue),key=e.target.dataset.cueField;cues[i][key]=['start','end'].includes(key)?Number(e.target.value):e.target.value;showCue(cues[i])}});
document.addEventListener('change',e=>{if(e.target.matches('[data-neural-voice]')){stopNative();choose(e.target.value)}if(e.target.id==='source-lang')$('#target-label').textContent=e.target.value==='en'?'German':'English'});
$('#close-dialog').onclick=()=>{$('#lesson-dialog').close();sceneToken++;stopNative();stopVoice()};$('#lesson-dialog').addEventListener('close',()=>{sceneToken++;stopNative();stopVoice()});
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.speak!==undefined){b.setAttribute('aria-busy','true');try{await speak(b.dataset.speak)}finally{b.removeAttribute('aria-busy')}return}if(b.dataset.lesson){openLesson(b.dataset.lesson);return}if(b.dataset.customSave){let w=b.dataset.customSave;saved=saved.includes(w)?saved.filter(x=>x!==w):[...saved,w];persist('wortreise-saved',saved);syncSaved();toast(saved.includes(w)?'Added to your word collection.':'Removed from your word collection.');return}if(b.dataset.insert){let input=document.getElementById(b.dataset.target);let start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText(b.dataset.insert,start,end,'end');input.focus();input.dispatchEvent(new Event('input',{bubbles:true}));return}if(b.dataset.sound!==undefined){let s=sounds[Number(b.dataset.sound)];$('#sound-detail').innerHTML=`<h3>${esc(s[0])} · Listen & feel the sound</h3><p>${esc(s[2])}</p><div class="row">${soundButton(s[3])}<strong lang="de">${esc(s[3])}</strong><span class="muted">${esc(s[4])}</span></div>`;speak(s[3]);return}if(b.dataset.deleteCue!==undefined){cues.splice(Number(b.dataset.deleteCue),1);renderCues();return}const action=b.dataset.action;try{switch(action){case'stop':sceneToken++;stopNative();stopVoice();$$('audio,video').forEach(el=>el.pause());break;case'listen-practice':await speak($('#speak-text').value);break;case'spell-practice':sceneToken++;stopVoice();try{await spellWord($('#speak-text').value,rate)}catch(error){$('#spelling-status').textContent=error.message;throw error}break;case'repeat-practice':{let token=++sceneToken;for(let i=0;i<3;i++){if(token!==sceneToken)break;await speak($('#speak-text').value)}break}case'record':stopNative();stopVoice();await toggleRecord();break;case'recognize':stopNative();stopVoice();recognize();break;case'dictate':dictationWord=words.filter(w=>!w.de.includes('…'))[Math.floor(Math.random()*words.filter(w=>!w.de.includes('…')).length)].de;$('#dictation').value='';$('#dictation-feedback').textContent='Listen, then type what you hear.';await speak(dictationWord);break;case'check-dictation':if(!dictationWord)return toast('Play a practice phrase first.');$('#dictation-feedback').textContent=normalize($('#dictation').value)===normalize(dictationWord)?'✓ Genau! That’s right. Try saying it aloud.':`Almost. The phrase is “${dictationWord}”. Compare the letters and listen again.`;break;case'reveal-dictation':$('#dictation-feedback').textContent=dictationWord||'Play a phrase first.';break;case'swap':$('#source-lang').value=$('#source-lang').value==='en'?'de':'en';$('#target-label').textContent=$('#source-lang').value==='en'?'German':'English';if(translationText)$('#translate-input').value=translationText;translationText='';$('#translation').textContent='Ready for your next translation.';break;case'translate':b.disabled=true;$('#translate-status').textContent='Finding the words…';try{let from=$('#source-lang').value;let text=await translateText($('#translate-input').value,from,from==='en'?'de':'en');translationText=text;translationLang=from==='en'?'de':'en';$('#translation').textContent=text;$('#translate-status').textContent='Translation ready. Listen, then try it yourself.'}catch(err){$('#translate-status').textContent=err.message}finally{b.disabled=false}break;case'hear-translation':if(!translationText)return toast('Translate some text first.');await speak(translationText,translationLang==='de'?'de-DE':'en-GB');break;case'copy-translation':if(!translationText)return toast('Translate some text first.');await navigator.clipboard.writeText(translationText);toast('Translation copied.');break;case'practice-translation':if(!translationText)return toast('Translate some text first.');location.hash='sounds';setTimeout(()=>{if($('#speak-text'))$('#speak-text').value=translationText},0);break;case'caption-translation':if(!translationText)return toast('Translate some text first.');cues=[{start:0,end:5,speaker:'',tone:'',sound:'',text:translationText,translation:$('#translate-input').value}];renderCues();showCue(cues[0]);location.hash='captions';break;case'sample-captions':cues=sampleCues();renderCues();showCue(cues[0]);break;case'play-captions':{let token=++sceneToken;for(let c of cues){if(token!==sceneToken||!$('#live-caption'))break;showCue(c);await speak(c.text,$('#media-lang').value==='english'?'en-GB':'de-DE')}break}case'add-cue':{let start=cues.length?cues[cues.length-1].end:0;cues.push({start,end:start+3,speaker:'',tone:'',sound:'',text:'',translation:''});renderCues();break}case'transcribe':await transcribe();break;case'cancel-transcription':cancelTranscription();$('#caption-status').textContent='Transcription cancelled. You can try again or import captions.';break;case'translate-captions':{if(!cues.length)return toast('Add or generate captions first.');b.disabled=true;let count=0;try{const from=$('#media-lang').value==='german'?'de':'en';for(let c of cues){if(c.text.trim()){c.translation=await translateText(c.text,from,from==='de'?'en':'de');count++;$('#caption-status').textContent=`Translated ${count} caption${count===1?'':'s'}…`}}renderCues();$('#caption-status').textContent='Translations ready. Review each line before exporting.'}catch(err){renderCues();$('#caption-status').textContent=`${count} captions translated. ${err.message}`}finally{b.disabled=false}break}case'export-srt':exportCaptions(false);break;case'export-vtt':exportCaptions(true);break;case'check-quiz':{let ok=normalize($('#quiz-answer').value)===normalize(currentLesson.quiz[quizIndex][1]);$('#quiz-feedback').textContent=ok?'✓ Genau! You’ve got it.':'Try again. Listen to the examples, and check the special characters.';if(ok){passed.add(quizIndex);if(passed.size===currentLesson.quiz.length){$('#complete-lesson').disabled=false;$('#complete-lesson').textContent='Complete lesson ✓'}}break}case'show-quiz':$('#quiz-feedback').textContent='Answer: '+currentLesson.quiz[quizIndex][1]+'. Type it yourself, then check it.';break;case'next-quiz':quizIndex=(quizIndex+1)%currentLesson.quiz.length;renderQuiz();break;case'complete-lesson':if(passed.size<currentLesson.quiz.length)return;if(!progress.includes(currentLesson.id)){progress.push(currentLesson.id);persist('wortreise-progress',progress)}$('#lesson-dialog').close();toast('Wunderbar! Another little step forward.');$('#home').innerHTML=home();$('#learn').innerHTML=learn();syncSaved();break;case'play-lesson':{let token=++sceneToken;for(let s of currentLesson.scene){if(token!==sceneToken)break;await speak(s[2])}break}}}catch(err){toast(err.message||'Something could not finish. Please try again.')}});
async function toggleRecord(){if(recorder?.state==='recording'){recorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('Recording is unavailable here. Try a current browser over HTTPS.');let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true})}catch{return toast('Microphone access was not granted. You can still listen and repeat aloud.')}let chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{clearTimeout(recordTimer);stream.getTracks().forEach(t=>t.stop());if(recordURL)URL.revokeObjectURL(recordURL);recordURL=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));if($('#recording')){$('#recording').src=recordURL;$('#recording').hidden=false;$('#record-btn').textContent='● Record again';$('#record-btn').classList.remove('recording')}};recorder.start();$('#record-btn').textContent='■ Stop recording';$('#record-btn').classList.add('recording');recordTimer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop()},30000)}
function recognize(){let SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('Speech recognition is not supported here. Record and compare your voice instead.');let r=new SR();r.lang='de-DE';r.interimResults=false;r.maxAlternatives=1;$('#speech-feedback').textContent='Listening… say the practice phrase.';r.onresult=e=>{let text=e.results[0][0].transcript;if($('#speech-feedback'))$('#speech-feedback').textContent=`Heard: “${text}”. ${normalize(text)===normalize($('#speak-text').value)?'The words match! Keep practising the sounds.':'Compare with the model and try again.'}`};r.onerror=e=>{if($('#speech-feedback'))$('#speech-feedback').textContent=`Speech recognition could not finish (${e.error}). Try recording and comparing instead.`};r.onend=()=>{if($('#speech-feedback')?.textContent.startsWith('Listening'))$('#speech-feedback').textContent='No speech detected. Please try again.'};r.start()}
document.querySelector('header').insertAdjacentHTML('afterend',`<div class="voice-dock"><div class="voice-dock-title"><span class="status-dot"></span> YOUR VOICE, YOUR FREQUENCY <small>No API key. Generated on your device.</small></div><label class="voice-choice">German voice <select data-neural-voice aria-label="German neural voice"><option value="de_DE-thorsten-medium">Thorsten · Male · Fast neural</option><option value="de_DE-thorsten-high">Thorsten · Male · Studio</option><option value="de_DE-kerstin-low">Kerstin · Female · Neural</option><option value="device">Device voice · Compatibility</option></select></label><button class="pill" id="preview-voice">▷ Preview voice</button><button class="pill" data-action="stop">Stop ◼</button><span data-voice-status role="status">First use sets up the voice. Later phrases reuse the engine.</span></div>`);$('[data-neural-voice]').value=selection();$('#preview-voice').onclick=()=>speak('Hallo! Ich freue mich, mit dir Deutsch zu lernen. Die Straße ist schön und die Äpfel sind grün.');
$('#help').onclick=()=>toast('Start with the learning path. Tap ▷ to listen. Your progress and saved words stay on this device. Caption media stays in memory; translation uses MyMemory.');route();

$('.skip').addEventListener('click',e=>{e.preventDefault();$('#content').focus();$('#content').scrollIntoView({block:'start'})});

document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a||a.classList.contains('skip'))return;const id=a.getAttribute('href').slice(1),section=document.getElementById(id);if(!section)return;e.preventDefault();history.replaceState(null,'','#'+id);section.scrollIntoView({behavior:'instant',block:'start'})});
